        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public void VertexArrayVertexBuffers(uint vaobj, uint first, ReadOnlySpan<uint> buffers, ReadOnlySpan<nint> offsets, ReadOnlySpan<int> strides)
        {
            if (offsets.Length != buffers.Length) {
                throw new ArgumentException("Span lengths controlled by count must match.", nameof(offsets));
            }
            if (strides.Length != buffers.Length) {
                throw new ArgumentException("Span lengths controlled by count must match.", nameof(strides));
            }
            fixed (uint* buffersPtr = buffers)
            {
                fixed (nint* offsetsPtr = offsets)
                {
                    fixed (int* stridesPtr = strides)
                    {
                        Context.glVertexArrayVertexBuffers(vaobj, first, checked((int)buffers.Length), buffersPtr, offsetsPtr, stridesPtr);
                    }
                }
            }
        }

